CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY);
INSERT OR IGNORE INTO schema_version VALUES(1);
CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL,category_id INTEGER NOT NULL REFERENCES categories(id),price INTEGER NOT NULL CHECK(price BETWEEN 1 AND 10000000),original_price INTEGER CHECK(original_price IS NULL OR original_price>=price),featured INTEGER NOT NULL DEFAULT 0 CHECK(featured IN(0,1)),is_new INTEGER NOT NULL DEFAULT 0 CHECK(is_new IN(0,1)),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS product_images(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL REFERENCES products(id),path TEXT NOT NULL,position INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS variants(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL REFERENCES products(id),sku TEXT NOT NULL UNIQUE,size TEXT NOT NULL,color TEXT NOT NULL,stock INTEGER NOT NULL CHECK(stock BETWEEN 0 AND 1000000),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),UNIQUE(product_id,size,color));
CREATE TABLE IF NOT EXISTS administrators(id INTEGER PRIMARY KEY,username TEXT NOT NULL UNIQUE,salt TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'admin' CHECK(role='admin'));
CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1),value TEXT NOT NULL);
INSERT OR IGNORE INTO settings VALUES(1,'{"name":"لمسة | LAMSA","tagline":"أناقتك تبدأ من هنا","hero_text":"اكتشفي أحدث صيحات الموضة النسائية التي تجمع بين الأناقة والراحة.","phone":"","whatsapp":"","instagram":"","about":"لمسة للأناقة اليومية. متجر تجريبي قيد التجهيز؛ جميع المنتجات والصور أمثلة توضيحية.","shipping_policy":"مسودة: تُحدَّد مناطق التوصيل ورسومها بعد اعتماد التاجر.","returns_policy":"مسودة: يضيف التاجر شروط الاستبدال والإرجاع بعد مراجعتها.","privacy_policy":"مسودة: تُستخدم بيانات الطلب لتنفيذه؛ تُعتمد سياسة الخصوصية قبل الإطلاق.","terms":"مسودة شروط الاستخدام؛ لا يُعد هذا المتجر التجريبي متجراً جاهزاً للبيع.","orders_enabled":false,"cod_enabled":false}');
CREATE TABLE IF NOT EXISTS shipping_regions(id INTEGER PRIMARY KEY,region TEXT NOT NULL,city TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN(0,1)),cod_enabled INTEGER NOT NULL DEFAULT 0 CHECK(cod_enabled IN(0,1)),fee INTEGER NOT NULL DEFAULT 0 CHECK(fee BETWEEN 0 AND 100000),UNIQUE(region,city));
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY,number TEXT NOT NULL UNIQUE,idempotency_key TEXT NOT NULL UNIQUE,request_hash TEXT NOT NULL,customer TEXT NOT NULL,shipping_region_id INTEGER NOT NULL REFERENCES shipping_regions(id),subtotal INTEGER NOT NULL CHECK(subtotal>=0),shipping_fee INTEGER NOT NULL CHECK(shipping_fee>=0),total INTEGER NOT NULL CHECK(total=subtotal+shipping_fee),status TEXT NOT NULL DEFAULT 'new' CHECK(status IN('new','preparing','shipped','delivered','cancelled')),payment_method TEXT NOT NULL CHECK(payment_method='cod'),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id),variant_id INTEGER NOT NULL REFERENCES variants(id),name TEXT NOT NULL,size TEXT NOT NULL,color TEXT NOT NULL,sku TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 20),unit_price INTEGER NOT NULL CHECK(unit_price>0));
CREATE INDEX IF NOT EXISTS idx_products_category ON products(category_id,active);
CREATE INDEX IF NOT EXISTS idx_variants_product ON variants(product_id,active,stock);
CREATE INDEX IF NOT EXISTS idx_orders_status ON orders(status);
CREATE INDEX IF NOT EXISTS idx_order_items_order ON order_items(order_id);
